import { test, expect } from '@playwright/test';

test.describe('Retry Button on Network Timeout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should display retry button when network request times out', async ({ page }) => {
    // Intercept the initial API request and simulate a timeout
    await page.route('**/api/data', (route) => {
      route.abort('timedout');
    });

    // Click the button that triggers the API call
    const fetchDataButton = page.getByRole('button', { name: /fetch data/i });
    await fetchDataButton.click();

    // Wait for the timeout error state to appear
    await page.waitForTimeout(500);

    // Verify the error message is displayed
    const errorMessage = page.getByText(/network request timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify the retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify the retry button has the correct label
    await expect(retryButton).toHaveText('Retry');

    // Verify the retry button is enabled
    await expect(retryButton).toBeEnabled();

    // Click the retry button
    await retryButton.click();

    // Verify the retry button is disabled while retrying
    await expect(retryButton).toBeDisabled();

    // Wait for the retry request to complete successfully
    await page.waitForTimeout(500);

    // Verify the error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify the data is now displayed
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).toBeVisible();
    const dataContent = page.getByText(/data loaded successfully/i);
    await expect(dataContent).toBeVisible();
  });

  test('should handle multiple retry attempts and display final error', async ({ page }) => {
    // Intercept the API request and simulate timeout for the first two attempts
    let attemptCount = 0;
    await page.route('**/api/data', (route) => {
      attemptCount++;
      if (attemptCount <= 2) {
        route.abort('timedout');
      } else {
        route.continue();
      }
    });

    // Click the button to trigger the first API call
    const fetchDataButton = page.getByRole('button', { name: /fetch data/i });
    await fetchDataButton.click();

    // Wait for the first timeout
    await page.waitForTimeout(500);

    // Verify retry button is visible after first timeout
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click retry button (second attempt)
    await retryButton.click();
    await page.waitForTimeout(500);

    // Verify retry button is still visible after second timeout
    await expect(retryButton).toBeVisible();

    // Click retry button (third attempt - should succeed)
    await retryButton.click();
    await page.waitForTimeout(500);

    // Verify data is now displayed
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).toBeVisible();
    const dataContent = page.getByText(/data loaded successfully/i);
    await expect(dataContent).toBeVisible();

    // Verify retry button is no longer visible after success
    await expect(retryButton).not.toBeVisible();
  });
});
